    async def xdsl_setting(
        self,
        *,
        reseller_fast_modem_shipping: bool | None = None,
        reseller_modem_basic_config: bool | None = None,
    ) -> None:
        """
        POST /1.0/me/xdsl/setting

        Change xdsl settings linked to the nichandle

        Args:
            reseller_fast_modem_shipping: Send the modem as soon as possible, do not
                wait the xdsl line to be active
            reseller_modem_basic_config: Let the modem with vendor configuration. It
                prevent to apply the config managed by ovh manager
        """
        await self._client.request(
            "POST",
            "/1.0/me/xdsl/setting",
            body={
                "resellerFastModemShipping": reseller_fast_modem_shipping,
                "resellerModemBasicConfig": reseller_modem_basic_config,
            },
        )
